<script setup lang="ts">
import type {components} from '../../shared/api'
import type {ProfileDocument,ProfileSection} from './profile-api'
import {attitudeOptions,type Catalogue} from './profile-fields'
import ProfileReferencePicker from './ProfileReferencePicker.vue'
import PracticePreferences from './PracticePreferences.vue'
import ProfileVisibility from './ProfileVisibility.vue'
const props=defineProps<{modelValue:ProfileDocument;section:ProfileSection;catalogue:Catalogue;partners:components['schemas']['ParticipantView'][];ru:boolean}>()
const emit=defineEmits<{'update:modelValue':[ProfileDocument]}>()
function update(section:ProfileSection,key:string,value:unknown){emit('update:modelValue',{...props.modelValue,[section]:{...props.modelValue[section],[key]:value}})}
function values(key:string){return props.modelValue.preferences?.[key as 'devices']??[]}
const itemGroups=[['devices','Девайсы','Devices'],['body-parts','Части тела','Body parts'],['materials','Материалы','Materials'],['role-scenarios','Сценарии','Scenarios'],['venues','Места','Venues']]
function setItems(key:string,ids:string[]){update('preferences',key,ids.map(uid=>values(key).find(r=>r.uid===uid)??{uid,attitude:'not_specified',conditions:''}))}
function setItem(key:string,uid:string,field:string,value:string){update('preferences',key,values(key).map(r=>r.uid===uid?{...r,[field]:value}:r))}
</script>
<template><div class="profile-section-editor">
<template v-if="section==='identity'"><label>{{ru?'Имя':'Display name'}}<input :value="modelValue.identity.display_name" maxlength="100" required autocomplete="nickname" @input="update('identity','display_name',($event.target as HTMLInputElement).value)"></label><label>{{ru?'О себе':'About me'}}<textarea :value="modelValue.identity.bio" maxlength="2000" rows="4" @input="update('identity','bio',($event.target as HTMLTextAreaElement).value)"/></label><div class="profile-field-pair"><label v-for="field in [['biological_sex_uid','biological-sex','Биологический пол','Biological sex'],['gender_uid','genders','Гендер','Gender']]" :key="field[0]">{{field[ru?2:3]}}<select :value="modelValue.identity[field[0] as 'gender_uid']??''" @change="update('identity',field[0]!,($event.target as HTMLSelectElement).value||null)"><option value="">{{ru?'Не указано':'Not specified'}}</option><option v-for="item in catalogue[field[1]!]" :key="item.uid" :value="item.uid">{{item.name}}</option></select></label></div></template>
<template v-else-if="section==='dynamics'"><fieldset><legend>{{ru?'Самоописание роли':'Role interests'}}</legend><p class="muted">{{ru?'Эти метки не меняют полномочия в отношениях.':'These labels do not change relationship permissions.'}}</p><label v-for="role in ['dominant','submissive','switch']" :key="role" class="profile-check"><input type="checkbox" :checked="modelValue.dynamics?.profile_labels?.includes(role as 'switch')" @change="update('dynamics','profile_labels',modelValue.dynamics?.profile_labels?.includes(role as 'switch')?modelValue.dynamics.profile_labels.filter(r=>r!==role):[...(modelValue.dynamics?.profile_labels??[]),role])">{{role}}</label></fieldset><ProfileReferencePicker v-for="field in [['relationship_type_uids','relationship-types','Виды отношений','Relationship types'],['composition_uids','participant-compositions','Состав участников','Participant compositions'],['interaction_format_uids','interaction-formats','Форматы взаимодействия','Interaction formats']]" :key="field[0]" :model-value="modelValue.dynamics?.[field[0] as 'composition_uids']??[]" :items="catalogue[field[1]!]??[]" :label="field[ru?2:3]!" :ru="ru" @update:model-value="update('dynamics',field[0]!,$event)"/><div v-for="field in [['sex_preference','biological-sex','Предпочтения по полу','Sex preferences'],['gender_preference','genders','Предпочтения по гендеру','Gender preferences']]" :key="field[0]"><label>{{field[ru?2:3]}}<select :value="modelValue.dynamics?.[field[0] as 'sex_preference']?.mode??'not_specified'" @change="update('dynamics',field[0]!,{mode:($event.target as HTMLSelectElement).value,uids:[]})"><option value="not_specified">{{ru?'Не указано':'Not specified'}}</option><option value="any">{{ru?'Любые':'Any'}}</option><option value="selected">{{ru?'Выбранные':'Selected'}}</option></select></label><ProfileReferencePicker v-if="modelValue.dynamics?.[field[0] as 'sex_preference']?.mode==='selected'" :model-value="modelValue.dynamics[field[0] as 'sex_preference']?.uids??[]" :items="catalogue[field[1]!]??[]" :label="field[ru?2:3]!" :ru="ru" @update:model-value="update('dynamics',field[0]!,{mode:'selected',uids:$event})"/></div></template>
<template v-else-if="section==='preferences'"><PracticePreferences :model-value="modelValue.preferences?.practices??[]" :catalogue="catalogue" :ru="ru" @update:model-value="update('preferences','practices',$event)"/><details v-for="group in itemGroups" :key="group[0]" class="profile-extra"><summary>{{group[ru?1:2]}}</summary><ProfileReferencePicker :model-value="values(group[0]!.replaceAll('-','_')).map(r=>r.uid)" :items="catalogue[group[0]!]??[]" :label="group[ru?1:2]!" :ru="ru" @update:model-value="setItems(group[0]!.replaceAll('-','_'),$event)"/><div v-for="item in values(group[0]!.replaceAll('-','_'))" :key="item.uid" class="profile-item-condition"><strong>{{catalogue[group[0]!]?.find(r=>r.uid===item.uid)?.name}}</strong><label>{{ru?'Отношение':'Preference'}}<select :value="item.attitude" @change="setItem(group[0]!.replaceAll('-','_'),item.uid,'attitude',($event.target as HTMLSelectElement).value)"><option v-for="option in attitudeOptions" :key="option[0]" :value="option[0]">{{option[ru?1:2]}}</option></select></label><label>{{ru?'Условия':'Conditions'}}<textarea :value="item.conditions" maxlength="2000" rows="2" @input="setItem(group[0]!.replaceAll('-','_'),item.uid,'conditions',($event.target as HTMLTextAreaElement).value)"/></label></div></details></template>
<template v-else-if="section==='boundaries'"><p class="muted">{{ru?'Табу и условия берутся из ваших предпочтений. Их можно изменить во вкладке «Предпочтения».':'Taboos and conditions use your practice preferences. Change them in Preferences.'}}</p><div v-for="status in ['taboo','conditional']" :key="status"><h4>{{status==='taboo'?(ru?'Жёсткие табу':'Hard limits'):(ru?'Только при условиях':'Conditional')}}</h4><p v-for="item in modelValue.preferences?.practices?.filter(p=>p.attitude===status)" :key="item.practice_uid">{{catalogue.practices?.find(p=>p.uid===item.practice_uid)?.name}} <small>{{item.conditions}}</small></p><p v-if="!modelValue.preferences?.practices?.some(p=>p.attitude===status)" class="muted">{{ru?'Не указано':'Not specified'}}</p></div><label>{{ru?'Что важно учитывать':'What matters to me'}}<textarea :value="modelValue.boundaries?.notes" maxlength="4000" rows="5" @input="update('boundaries','notes',($event.target as HTMLTextAreaElement).value)"/></label></template>
<template v-else-if="section==='health'"><p class="profile-private-label">{{ru?'По умолчанию только я':'Private by default'}}</p><ProfileReferencePicker v-for="field in [['condition_uids','health-conditions','Состояния здоровья','Health conditions'],['allergen_uids','allergens','Аллергены','Allergens'],['care_practice_uids','practices','Восстановление и забота','Recovery & care']]" :key="field[0]" :model-value="modelValue.health?.[field[0] as 'condition_uids']??[]" :items="catalogue[field[1]!]??[]" :label="field[ru?2:3]!" :ru="ru" @update:model-value="update('health',field[0]!,$event)"/><label>{{ru?'Личные пояснения и пожелания':'Personal notes & care wishes'}}<textarea :value="modelValue.health?.notes" maxlength="4000" rows="4" @input="update('health','notes',($event.target as HTMLTextAreaElement).value)"/></label></template>
<ProfileVisibility v-else :model-value="modelValue.visibility??{sections:[]}" :partners="partners" :ru="ru" @update:model-value="emit('update:modelValue',{...modelValue,visibility:$event})"/>
</div></template>
